#!/usr/bin/env python3
"""Loads quadruped_stairs.xml in MuJoCo Warp and runs a few steps. Generated by MJForge 0.1.0.

Buffer sizes measured while the model settled for 1.5 s (simulate in MJForge for motion peaks): 4 contacts, 8 broadphase candidate pairs, 12 constraint
rows per world. Raise them if MJWarp reports an overflow (e.g. rougher terrain, more robots).
"""
import os

import mujoco
import mujoco_warp as mjw
import warp as wp

XML = os.path.join(os.path.dirname(os.path.abspath(__file__)), "quadruped_stairs.xml")
NWORLD = 1024
NCONMAX = 16  # contacts per world (must also cover MJWarp's broadphase pairs)
NJMAX = 24  # constraint rows per world

mjm = mujoco.MjModel.from_xml_path(XML)
mjd = mujoco.MjData(mjm)
if mjm.nkey > 0:
  mujoco.mj_resetDataKeyframe(mjm, mjd, 0)  # start pose
mujoco.mj_forward(mjm, mjd)

m = mjw.put_model(mjm)
d = mjw.put_data(mjm, mjd, nworld=NWORLD, nconmax=NCONMAX, njmax=NJMAX)

for _ in range(100):
  mjw.step(m, d)
wp.synchronize()
print(f"stepped {NWORLD} worlds of {mjm.nq} qpos / {mjm.nu} actuators")
